// Web Atölyesi — 100 seviyelik öğrenme yolu üretici.
// Çalıştır: node tools/learn-levels/web-lab.gen.mjs  →  public/runner-assets/web-lab-runner/levels.js
// Her seviyenin bir "çözümü" vardır; üretici, başlangıç kodunun görevi GEÇMEDİĞİNİ ve çözümün GEÇTİĞİNİ doğrular.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const OUT = path.resolve(here, '../../public/runner-assets/web-lab-runner/levels.js');

const baseHtml = (body, title = 'Benim Sayfam') => `<!doctype html>\n<html lang="tr">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>${title}</title>\n</head>\n<body>\n${body}\n</body>\n</html>`;
const baseCss = 'body {\n  font-family: Arial, sans-serif;\n  padding: 24px;\n}';

const levels = [];
const H = (re, m) => ['html', re, m];
const C = (re, m) => ['css', re, m];
const J = (re, m) => ['js', re, m];
// css kural kalıbı: sel { ... prop: val }
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const cr = (sel, prop, val = '[^;}]+') => new RegExp(`${esc(sel)}\\s*\\{[^}]*\\b${prop}\\s*:\\s*(?:${val})`, 'is');
const tag = (t, inner = '') => new RegExp(`<${t}\\b[^>]*>${inner}`, 'i');

function add(track, title, story, goal, hints, xp, o) {
  levels.push({
    track, title, story, goal, hints, xp,
    files: { html: o.full ? o.full : baseHtml(o.body ?? '  '), css: baseCss + (o.css ? '\n\n' + o.css : ''), js: o.js ?? '' },
    rules: o.rules,
    success: o.success,
    sol: { html: o.sfull ? o.sfull : baseHtml(o.sbody ?? o.body ?? '  '), css: baseCss + (o.scss ?? (o.css ? '\n\n' + o.css : '') ? '\n\n' + (o.scss ?? o.css) : ''), js: o.sjs ?? o.js ?? '' },
  });
}
const HT = (...a) => add('HTML', ...a);
const CS = (...a) => add('CSS', ...a);
const JS = (...a) => add('JavaScript', ...a);
const PR = (...a) => add('Proje', ...a);

