if (levels.length !== 100) throw new Error('Seviye sayısı ' + levels.length + ' ' + JSON.stringify(levels.reduce((a, l) => ((a[l.track] = (a[l.track] || 0) + 1), a), {})));

// ---- doğrulama: başlangıç GEÇMEMELİ, çözüm GEÇMELİ
const run = (rules, f) => { for (const [t, re, m] of rules) { if (!re.test(f[t])) return m; } return null; };
let bad = 0;
levels.forEach((l, i) => {
  const s = run(l.rules, l.files);
  if (s === null) { console.error(`#${i + 1} ${l.title}: BAŞLANGIÇ zaten geçiyor!`); bad++; }
  const f = run(l.rules, { html: l.sol.html, css: l.sol.css, js: l.sol.js });
  if (f !== null) { console.error(`#${i + 1} ${l.title}: ÇÖZÜM geçmiyor -> ${f}`); bad++; }
  for (const [lab, code] of [["başlangıç", l.files.js], ["çözüm", l.sol.js]]) { try { new Function(code); } catch (e) { console.error(`#${i + 1} ${l.title}: ${lab} JS sözdizimi hatası: ${e.message}`); bad++; } }
});
if (bad) { console.error(bad + ' sorun'); process.exit(1); }

const data = levels.map((l) => ({ track: l.track, title: l.title, story: l.story, goal: l.goal, hints: l.hints, xp: l.xp, files: l.files, rules: l.rules.map(([t, re, m]) => [t, re.source, re.flags, m]), success: l.success }));
const js = `/* Web Atölyesi — 100 seviyelik öğrenme yolu (otomatik üretildi: tools/learn-levels/web-lab.gen.mjs, elle düzenlemeyin). */
(function () {
  var DATA = ${JSON.stringify(data)};
  var KEY = { html: 'html', css: 'css', js: 'js' };
  window.WEB_LAB_LEVELS = DATA.map(function (d) {
    var rules = d.rules.map(function (r) { return { t: r[0], re: new RegExp(r[1], r[2]), m: r[3] }; });
    return {
      track: d.track, title: d.title, story: d.story, goal: d.goal, hints: d.hints, xp: d.xp, files: d.files, success: d.success,
      check: function (ctx) {
        for (var i = 0; i < rules.length; i++) {
          if (!rules[i].re.test(ctx[KEY[rules[i].t]] || '')) return rules[i].m;
        }
        return null;
      }
    };
  });
})();
`;
fs.writeFileSync(OUT, js);
const by = levels.reduce((a, l) => ((a[l.track] = (a[l.track] || 0) + 1), a), {});
console.log(`100 seviye ${JSON.stringify(by)} -> ${path.relative(process.cwd(), OUT)} (${(js.length / 1024).toFixed(1)} KB)`);
